    // ── Certificates (JS dynamic) ──
    // Course descriptions
    cert_epa608_desc: { es: 'Paquete completo: 700 preguntas de preparación, examen oficial, y honorarios del proctor (4 hrs máx). Si no aprueba, paga el costo total nuevamente.', en: 'Complete package: 700 prep questions, official exam, and proctor fees (4 hrs max). If you fail, you pay the full cost again.' },
    cert_osha_desc: { es: 'Certificación OSHA 30 Horas. Incluye 700 preguntas de preparación y acceso al sitio web oficial para completar el curso y examen a tu propio ritmo.', en: 'OSHA 30 Hours Certification. Includes 700 prep questions and access to the official website to complete the course and exam at your own pace.' },
    cert_a2l_desc: { es: 'Paquete completo: 700 preguntas de preparación, examen oficial, y honorarios del proctor (4 hrs máx). Cubre R-32, R-454B, detección de fugas y regulaciones.', en: 'Complete package: 700 prep questions, official exam, and proctor fees (4 hrs max). Covers R-32, R-454B, leak detection, and regulations.' },
    cert_heating_desc: { es: 'Paquete completo: 700 preguntas de preparación, examen oficial, y honorarios del proctor (4 hrs máx). Cubre gas, furnaces, combustión y controles de seguridad.', en: 'Complete package: 700 prep questions, official exam, and proctor fees (4 hrs max). Covers gas, furnaces, combustion, and safety controls.' },
    cert_hvaccore_desc: { es: 'Paquete completo: 700 preguntas de preparación, examen oficial, y honorarios del proctor (4 hrs máx). Cubre refrigeración doméstica, comercial, industrial, controles y diagnóstico.', en: 'Complete package: 700 prep questions, official exam, and proctor fees (4 hrs max). Covers domestic, commercial, industrial refrigeration, controls, and diagnostics.' },
    cert_hvacr_desc: { es: 'Paquete completo: 749 preguntas de preparación de alto nivel. Cubre fundamentos, electricidad, heat pumps, sistemas comerciales, chillers, diagnóstico e industrial avanzado.', en: 'Complete package: 749 advanced-level prep questions. Covers fundamentals, electrical, heat pumps, commercial systems, chillers, diagnostics, and advanced industrial.' },
    cert_etcard_desc: { es: 'Paquete completo: 694 preguntas de preparación para la tarjeta ET. Cubre Ley de Ohm, NEC, conductores, canalizaciones, circuitos, motores, transformadores, grounding y seguridad eléctrica.', en: 'Complete package: 694 prep questions for the ET card. Covers Ohm\'s Law, NEC, conductors, raceways, circuits, motors, transformers, grounding, and electrical safety.' },
    cert_natesenior_desc: { es: 'Paquete completo: 700 preguntas de nivel senior. Cubre AC avanzado, heat pumps, gas furnace, electricidad avanzada, airflow, comercial y diagnóstico avanzado.', en: 'Complete package: 700 senior-level questions. Covers advanced AC, heat pumps, gas furnace, advanced electrical, airflow, commercial, and advanced diagnostics.' },
    cert_hvaccore_name: { es: 'Refrigeración Comercial e Industrial', en: 'Commercial & Industrial Refrigeration' },

