    // ── Testimonials ──
    html_testimonial_1: { es: '"Gracias a Maestro HVACR pas\u00e9 mi examen EPA 608 al primer intento. Las preguntas del quiz son exactamente lo que viene en el examen real. \u00a1Recomendado al 100%!"', en: '"Thanks to Maestro HVACR I passed my EPA 608 exam on the first try. The quiz questions are exactly what appears on the real exam. 100% recommended!"' },
    html_testimonial_1_name: { es: 'Jos\u00e9 Ram\u00edrez', en: 'Jos\u00e9 Ram\u00edrez' },
    html_testimonial_1_author: { es: 'T\u00e9cnico HVAC \u2014 Los Angeles, CA', en: 'HVAC Technician \u2014 Los Angeles, CA' },
    html_testimonial_2: { es: '"Llevo 3 meses usando la app y ya complet\u00e9 hasta el nivel avanzado. Mi jefe me subi\u00f3 el sueldo porque ahora puedo diagnosticar problemas que antes no entend\u00eda. La inversi\u00f3n se paga sola."', en: '"I\'ve been using the app for 3 months and already completed up to the advanced level. My boss gave me a raise because now I can diagnose problems I didn\'t understand before. The investment pays for itself."' },
    html_testimonial_2_name: { es: 'Miguel Hern\u00e1ndez', en: 'Miguel Hern\u00e1ndez' },
    html_testimonial_2_author: { es: 'T\u00e9cnico Senior \u2014 Houston, TX', en: 'Senior Technician \u2014 Houston, TX' },
    html_testimonial_3: { es: '"Lo mejor es que todo est\u00e1 en espa\u00f1ol. Yo no hablo mucho ingl\u00e9s y siempre batallaba con los materiales de estudio. Con Maestro HVACR por fin entiendo todo. Ya tengo 2 certificados."', en: '"The best part is that everything is in Spanish. I don\'t speak much English and always struggled with study materials. With Maestro HVACR I finally understand everything. I already have 2 certificates."' },
    html_testimonial_3_name: { es: 'Carlos L\u00f3pez', en: 'Carlos L\u00f3pez' },
    html_testimonial_3_author: { es: 'Ayudante HVAC \u2014 Phoenix, AZ', en: 'HVAC Helper \u2014 Phoenix, AZ' },
    html_testimonial_4: { es: '"Soy due\u00f1o de mi empresa y inscrib\u00ed a mis 5 t\u00e9cnicos en Maestro HVACR. En 2 meses ya todos pasaron el nivel intermedio. Es la mejor herramienta para entrenar personal nuevo."', en: '"I own my company and enrolled my 5 technicians in Maestro HVACR. In 2 months they all passed the intermediate level. It\'s the best tool for training new staff."' },
    html_testimonial_4_name: { es: 'Roberto Flores', en: 'Roberto Flores' },
    html_testimonial_4_author: { es: 'Due\u00f1o HVAC Company \u2014 Dallas, TX', en: 'HVAC Company Owner \u2014 Dallas, TX' },

