    // ── Desafio motivational quotes ──
    ds_quote_1: { es: 'Cada batalla se gana antes de pelearla.', en: 'Every battle is won before it is fought.' },
    ds_quote_2: { es: 'Conoce a tu enemigo y con\u00f3cete a ti mismo y en cien batallas no ser\u00e1s derrotado.', en: 'Know your enemy and know yourself and in a hundred battles you will not be defeated.' },
    ds_quote_3: { es: 'En medio del caos, tambi\u00e9n hay oportunidad.', en: 'In the midst of chaos, there is also opportunity.' },
    ds_quote_4: { es: 'El supremo arte de la guerra es someter al enemigo sin luchar.', en: 'The supreme art of war is to subdue the enemy without fighting.' },
    ds_quote_5: { es: 'Las oportunidades se multiplican a medida que se aprovechan.', en: 'Opportunities multiply as they are seized.' },
    ds_quote_6: { es: 'El guerrero victorioso primero gana y despu\u00e9s va a la guerra. El guerrero derrotado primero va a la guerra y despu\u00e9s busca ganar.', en: 'The victorious warrior wins first and then goes to war. The defeated warrior goes to war first and then seeks to win.' },
    ds_quote_7: { es: 'El verdadero poder reside en la calma interior.', en: 'True power resides in inner calm.' },
    ds_quote_8: { es: 'El obst\u00e1culo es el camino.', en: 'The obstacle is the way.' },
    ds_quote_9: { es: 'No pierdas m\u00e1s tiempo discutiendo lo que debe ser un buen hombre. S\u00e9 uno.', en: 'Waste no more time arguing about what a good man should be. Be one.' },
    ds_quote_10: { es: 'La felicidad de tu vida depende de la calidad de tus pensamientos.', en: 'The happiness of your life depends on the quality of your thoughts.' },
    ds_quote_11: { es: 'El impedimento a la acci\u00f3n avanza la acci\u00f3n. Lo que se interpone en el camino se convierte en el camino.', en: 'The impediment to action advances action. What stands in the way becomes the way.' },
    ds_quote_12: { es: 'Tienes poder sobre tu mente, no sobre los eventos externos. Entiende esto y encontrar\u00e1s la fuerza.', en: 'You have power over your mind, not outside events. Realize this and you will find strength.' },
    ds_quote_13: { es: 'Nunca opaques al maestro. Haz que los que est\u00e1n arriba se sientan superiores.', en: 'Never outshine the master. Make those above you feel superior.' },
    ds_quote_14: { es: 'Conc\u00e9ntrate en el resultado final, no en los obst\u00e1culos del camino.', en: 'Focus on the end result, not the obstacles along the way.' },
    ds_quote_15: { es: 'Cuando pidas ayuda, apela al inter\u00e9s propio de la gente, nunca a su piedad.', en: 'When asking for help, appeal to people\'s self-interest, never to their mercy.' },
    ds_quote_16: { es: 'Usa la ausencia selectiva para aumentar el respeto y el honor.', en: 'Use selective absence to increase respect and honor.' },
    ds_quote_17: { es: 'Planifica hasta el final. El final es todo.', en: 'Plan all the way to the end. The ending is everything.' },
    ds_quote_18: { es: 'Domina el arte de la oportunidad. Nunca te apresures, la paciencia es poder.', en: 'Master the art of timing. Never rush, patience is power.' },
    ds_quote_19: { es: 'Aprende a mantener a la gente dependiente de ti.', en: 'Learn to keep others dependent on you.' },
    ds_quote_20: { es: 'Es mejor ser temido que amado, si no se puede ser ambas cosas.', en: 'It is better to be feared than loved, if you cannot be both.' },
    ds_quote_21: { es: 'Nunca se intente ganar por fuerza lo que se puede ganar por enga\u00f1o.', en: 'Never attempt to win by force what can be won by deception.' },
    ds_quote_22: { es: 'Los hombres ofenden antes al que aman que al que temen.', en: 'Men offend those they love before those they fear.' },
    ds_quote_23: { es: 'El que domina a otros es fuerte; el que se domina a s\u00ed mismo es poderoso.', en: 'He who conquers others is strong; he who conquers himself is powerful.' },
    ds_quote_24: { es: 'La disciplina es el puente entre metas y logros.', en: 'Discipline is the bridge between goals and accomplishment.' },
    ds_quote_25: { es: 'La victoria pertenece al m\u00e1s perseverante.', en: 'Victory belongs to the most persevering.' },
    ds_quote_26: { es: 'Lo que no te mata te hace m\u00e1s fuerte.', en: 'What does not kill you makes you stronger.' },
    ds_quote_27: { es: 'El \u00e9xito no es definitivo, el fracaso no es fatal: lo que cuenta es el valor de continuar.', en: 'Success is not final, failure is not fatal: it is the courage to continue that counts.' },
    ds_quote_28: { es: 'La excelencia no es un acto, sino un h\u00e1bito.', en: 'Excellence is not an act, but a habit.' },
    ds_quote_29: { es: 'La suerte favorece a la mente preparada.', en: 'Fortune favors the prepared mind.' },
    ds_quote_30: { es: 'No cuentes los d\u00edas, haz que los d\u00edas cuenten.', en: 'Don\'t count the days, make the days count.' },
    ds_quote_31: { es: 'El secreto de salir adelante es comenzar.', en: 'The secret of getting ahead is getting started.' },
    ds_quote_32: { es: 'El hombre que mueve monta\u00f1as comienza cargando peque\u00f1as piedras.', en: 'The man who moves mountains begins by carrying small stones.' },
    ds_quote_33: { es: 'La mejor venganza es un \u00e9xito masivo.', en: 'The best revenge is massive success.' },
    ds_quote_34: { es: 'Trabaja en silencio, deja que tu \u00e9xito haga el ruido.', en: 'Work in silence, let your success make the noise.' },
    ds_quote_35: { es: 'El dolor que sientes hoy ser\u00e1 la fuerza que sentir\u00e1s ma\u00f1ana.', en: 'The pain you feel today will be the strength you feel tomorrow.' },
    ds_quote_36: { es: 'Cree que puedes y ya est\u00e1s a medio camino.', en: 'Believe you can and you\'re halfway there.' },
    ds_quote_37: { es: 'Haz lo que temes y la muerte del miedo es segura.', en: 'Do the thing you fear and the death of fear is certain.' },
    ds_quote_38: { es: 'Un t\u00e9cnico preparado vale m\u00e1s que diez con suerte.', en: 'A prepared technician is worth more than ten lucky ones.' },
    ds_quote_39: { es: 'El conocimiento es tu herramienta m\u00e1s poderosa. \u00dasala.', en: 'Knowledge is your most powerful tool. Use it.' },
    ds_quote_40: { es: 'Cada pregunta que dominas es un paso m\u00e1s hacia tu certificado.', en: 'Every question you master is one more step toward your certificate.' },

